script:
let my_dialog = new frappe.ui.Dialog({
    title: "Enter First Name",
    fields: [
        {
            label: "First Name",
            fieldname: "first_name",
            fieldtype: "Data",
            reqd: 1
        }
    ],
    primary_action_label: "Submit",
    primary_action(values) {
        my_dialog.hide();

        frappe.route_options = {
            first_name: values.first_name
        };

        frappe.new_doc("Contact");
    }
});

my_dialog.show();
